import{_ as o,o as r,c as a,ae as t}from"./chunks/framework.EHGTsUvI.js";const u=JSON.parse('{"title":"Crop Silos","description":"","frontmatter":{"title":"Crop Silos"},"headers":[],"relativePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Utilities/cropsilos.md","filePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Utilities/cropsilos.md"}'),i={name:"Main/Main/GeneralKnowledge/Factorys&Utilities/Utilities/cropsilos.md"};function s(l,e,n,p,d,h){return r(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="crop-silos" tabindex="-1">Crop Silos <a class="header-anchor" href="#crop-silos" aria-label="Permalink to &quot;Crop Silos&quot;">​</a></h1><p>Crop Silos are storage buildings used to store harvested crops, allowing players to keep large quantities of crops for later use.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Crop Silos are used to store harvested crops without needing to keep them inside trailers or other vehicles.</p><p>They are particularly useful for storing crops that will later be used in production chains.</p><h2 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to Use&quot;">​</a></h2><h3 id="_1-place-the-crop-silo" tabindex="-1">1. Place the Crop Silo <a class="header-anchor" href="#_1-place-the-crop-silo" aria-label="Permalink to &quot;1. Place the Crop Silo&quot;">​</a></h3><p>Purchase and place the Crop Silo on your farm.</p><h3 id="_2-load-crops" tabindex="-1">2. Load Crops <a class="header-anchor" href="#_2-load-crops" aria-label="Permalink to &quot;2. Load Crops&quot;">​</a></h3><p>Bring harvested crops to the Crop Silo and unload them into the storage area.</p><h3 id="_3-store-crops" tabindex="-1">3. Store Crops <a class="header-anchor" href="#_3-store-crops" aria-label="Permalink to &quot;3. Store Crops&quot;">​</a></h3><p>The crops will remain stored inside the silo until they are needed.</p><h3 id="_4-remove-crops" tabindex="-1">4. Remove Crops <a class="header-anchor" href="#_4-remove-crops" aria-label="Permalink to &quot;4. Remove Crops&quot;">​</a></h3><p>When required, load the stored crops into a suitable vehicle or trailer for transportation or production.</p><h2 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td>Purchase Price</td><td>3,000 Coins</td></tr><tr><td>Storage Capacity</td><td>300 Crop Boxes</td></tr></tbody></table><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>No special license required.</li><li>No additional equipment required.</li></ul><h2 id="useful-information-tips" tabindex="-1">Useful Information &amp; Tips <a class="header-anchor" href="#useful-information-tips" aria-label="Permalink to &quot;Useful Information &amp; Tips&quot;">​</a></h2><ul><li>Crop Silos can store up to <strong>300 boxes of crops</strong>.</li><li>Useful for storing crops between harvests.</li><li>Can be used to stockpile crops for factories.</li><li>Helps reduce the amount of trailers needed for storage.</li><li>Particularly useful for large-scale farming and production chains.</li></ul>',20)])])}const f=o(i,[["render",s]]);export{u as __pageData,f as default};
